import { expect, test } from 'claude-code/testing'

// The exact calls Claude made in a real -p run: list, two requests, a short paste, two good pastes.
// It also prints each drawn pane after FRAMESJSON, which is how the demo clip is made.
const txt = (n: any): string => (typeof n === 'string' ? n : (n?.children ?? []).map(txt).join(' '))
test('Claude asks for two keys, a short paste is refused, and no value is ever shown', async ($, on) => {
  const env = (k: string) => 'process' + '.env.' + k // built at run time so no tool masks the sample
  const disk: Record<string, string> = { '/proj/src/upload.ts': `import Mux from '@mux/mux-node'\n\nconst mux = new Mux({ tokenId: ${env('MUX_TOKEN_ID')}, tokenSecret: ${env('MUX_TOKEN_SECRET')} })\n` }
  const said: string[] = []
  const toasts: string[] = []
  on('fs.read', async (_$: any, e: any) => { if (!(e.path in disk)) throw new Error('missing'); return { value: disk[e.path] } as any })
  on('fs.write', async (_$: any, e: any) => { disk[e.path] = String(e.text); return { value: undefined } as any })
  on('fs.list', async (_$: any, e: any) => {
    const kids = new Map<string, 'file' | 'dir'>()
    for (const k of Object.keys(disk)) if (k.startsWith(e.path + '/')) { const [h, ...t] = k.slice(e.path.length + 1).split('/'); kids.set(h, t.length ? 'dir' : 'file') }
    return { value: [...kids].map(([name, kind]) => ({ name, kind })) } as any
  })
  on('ui.render', async () => null as any)
  on('ui.open', async () => ({ value: { opened: true } }) as any)
  on('ui.toast', async (_$: any, e: any) => { toasts.push(String(e.text ?? e.message ?? '')); return { value: undefined } as any })
  on('prompt.submit', async (_$: any, e: any) => { said.push(e.text); return { text: e.text } as any })
  const listed: any = await $.tool.call({ tool: 'mcp__secrets-guard__env_list', file: '/proj/.env' } as any)
  const reqs = [{"key": "MUX_TOKEN_ID", "why": "Mux access token ID \u2014 lets src/upload.ts create video assets in your Mux account.", "link": "https://dashboard.mux.com/settings/access-tokens", "where": ["Open Mux dashboard \u2192 Settings \u2192 Access Tokens", "Click 'Generate new token', pick the environment, tick Mux Video (Read + Write)", "Copy the 'Access Token ID'"], "format": "UUID, 36 characters", "minLength": 36}, {"key": "MUX_TOKEN_SECRET", "why": "Mux secret key \u2014 pairs with MUX_TOKEN_ID to authenticate uploads.", "link": "https://dashboard.mux.com/settings/access-tokens", "where": ["Same token screen as MUX_TOKEN_ID", "Copy the 'Secret Key' \u2014 Mux shows it only once, at creation"], "format": "Long base64-style string", "minLength": 20}]
  const mount = () => $.ui.mount({ plugin: 'secrets-guard', surface: 'terminal', component: 'Pane', requestId: 'env', props: {}, viewport: { columns: 64, rows: 30 } } as any)
  const frames: any[] = []
  let ui = await mount()
  frames.push({ label: 'list', tree: await ui.drawn() })
  for (const r of reqs) await $.tool.call({ tool: 'mcp__secrets-guard__env_request', ...r, file: '/proj/.env' } as any)
  frames.push({ label: 'card', tree: await ui.drawn() })
  await ui.input({ key: 'paste', text: '3f2a9c1e-7b4d' })
  frames.push({ label: 'short', tree: await ui.drawn() })
  await ui.input({ key: 'paste', text: '3f2a9c1e-7b4d-4e8a-9c10-5d6e7f80a41c' })
  frames.push({ label: 'second', tree: await ui.drawn() })
  await ui.input({ key: 'paste', text: 'Zm9vYmFyYmF6cXV4ZmFrZXNlY3JldA' })
  frames.push({ label: 'saved', tree: await ui.drawn() })
  console.log('FRAMESJSON' + JSON.stringify({ frames, listed: listed.result, said, toasts }))
  expect(frames.length).toBe(5)
  expect(String(listed.result)).toContain('MUX_TOKEN_ID')
  expect(String(listed.result)).toContain('MUX_TOKEN_SECRET')
  const all = frames.map(f => txt(f.tree)).join(' | ')
  expect(all).not.toContain('3f2a9c1e-7b4d-4e8a-9c10-5d6e7f80a41c')
  expect(all).not.toContain('Zm9vYmFyYmF6cXV4ZmFrZXNlY3JldA')
  expect(said.join(' ')).not.toContain('3f2a9c1e')
  expect(disk['/proj/.env']).toContain('MUX_TOKEN_ID=3f2a9c1e-7b4d-4e8a-9c10-5d6e7f80a41c')
})

import { expect, test } from 'claude-code/testing'

import { checkValue, listKeys, missingKeys, readsIn, setKey } from './envfile'
import { isSecretFile, maskKeys, secretCommand } from './secrets'

test('secret files are recognised, examples are not', () => {
  for (const p of ['.env', '/app/.env.local', '~/.ssh/id_ed25519', 'certs/server.pem', '/home/me/.aws/credentials', 'config/secrets.yml', '.npmrc'])
    expect(isSecretFile(p)).toBe(true)
  for (const p of ['.env.example', '/app/.env.sample', '~/.ssh/id_ed25519.pub', 'README.md', 'src/env.ts', 'keyboard.tsx'])
    expect(isSecretFile(p)).toBe(false)
})

test('commands that would print a secret are stopped', () => {
  expect(secretCommand('cat .env')).toContain('.env')
  expect(secretCommand('grep API_KEY /app/.env.production')).toContain('.env.production')
  expect(secretCommand('ls && tail -5 ~/.ssh/id_rsa')).toContain('id_rsa')
  expect(secretCommand('env')).toContain('every environment variable')
  expect(secretCommand('python app.py < .env')).toContain('.env')
})

test('ordinary commands pass', () => {
  for (const c of ['ls -la', 'cat README.md', 'cp .env.example .env', 'env NODE_ENV=test npm test', 'git status', 'grep -r "process.env" src'])
    expect(secretCommand(c)).toBe(null)
})

test('keys in output are masked', () => {
  const fake = 'sk-ant-' + 'a'.repeat(30)
  const r = maskKeys(`key is ${fake}\nOPENAI_API_KEY=abcdefgh12345678\nAWS AKIA${'A'.repeat(16)}`)
  expect(r.count).toBe(3)
  expect(r.text).not.toContain(fake)
  expect(r.text).toContain('OPENAI_API_KEY=[masked]')
  expect(r.text).toContain('sk-a…[masked]')
})

test('plain text is left alone', () => {
  const t = 'Built 12 mods. tokens used: 4000. password reset link sent.'
  expect(maskKeys(t)).toEqual({ text: t, count: 0 })
})

test('Claude cannot open a .env file', async $ => {
  const r: any = await $.tool.call({ tool: 'Read', file_path: '/tmp/project/.env' } as any)
  expect(String(r.deny)).toContain('holds secrets')
})

test('the .env pane lists names with masked values and writes a pasted key', () => {
  const text = 'MUX_TOKEN_ID=44c819de-1111-2222-3333-4d5e6f70492b\nSHORT=abc12345\n# note\nEMPTY=\n'
  expect(listKeys(text)).toEqual([
    { name: 'MUX_TOKEN_ID', masked: 'hidden · 36 chars' },
    { name: 'SHORT', masked: 'hidden · 8 chars' },
    { name: 'EMPTY', masked: 'empty' },
  ])
  expect(setKey(text, 'SHORT', 'newvalue99')).toContain('SHORT=newvalue99\n')
  expect(setKey('A=1\n', 'B', 'two words')).toBe('A=1\nB="two words"\n')
  expect(checkValue('short', 8)).toContain('at least 8')
  expect(checkValue('a-long-enough-value', 8)).toBe(null)
})

test('a key pasted in the pane goes into .env, and Claude only hears that it is set', async ($, on) => {
  const disk: Record<string, string> = { '/fixture/.env': 'OPENAI_API_KEY=sk-test-000000000000000000001234\n' }
  const said: string[] = []
  on('fs.read', async (_$: any, e: any) => {
    if (!(e.path in disk)) throw new Error('missing')
    return { value: disk[e.path] } as any
  })
  on('fs.write', async (_$: any, e: any) => {
    disk[e.path] = String(e.text)
    return { value: undefined } as any
  })
  on('ui.render', async () => null as any)
  on('ui.open', async () => ({ value: { opened: true } }) as any)
  on('ui.toast', async () => ({ value: undefined }) as any)
  on('prompt.submit', async (_$: any, e: any) => {
    said.push(e.text)
    return { text: e.text } as any
  })
  const listed: any = await $.tool.call({ tool: 'mcp__secrets-guard__env_list', file: '/fixture/.env' } as any)
  expect(String(listed.result)).toContain('OPENAI_API_KEY  hidden · 32 chars')
  expect(String(listed.result)).not.toContain('sk-test')
  const asked: any = await $.tool.call({ tool: 'mcp__secrets-guard__env_request', key: 'MUX_TOKEN_ID', why: 'Uploads videos to Mux', where: ['Open Mux', 'Settings, then Access Tokens'], format: 'UUID, 36 characters', minLength: 36, file: '/fixture/.env' } as any)
  expect(String(asked.result)).toContain('wait')
  const ui = await $.ui.mount({ plugin: 'secrets-guard', surface: 'terminal', component: 'Pane', requestId: 'env', props: {}, viewport: { columns: 72, rows: 30 } } as any)
  expect(JSON.stringify(await ui.drawn())).toContain('KEY REQUEST')
  await ui.input({ key: 'paste', text: 'too-short' })
  expect(JSON.stringify(await ui.drawn())).toContain('at least 36')
  const fake = '44c819de-aaaa-bbbb-cccc-4d5e6f70492b'
  await ui.input({ key: 'paste', text: fake })
  expect(disk['/fixture/.env']).toContain(`MUX_TOKEN_ID=${fake}`)
  expect(said).toEqual(['[env] MUX_TOKEN_ID is now set in .env. Continue.'])
  const after = JSON.stringify(await ui.drawn())
  expect(after).not.toContain(fake)
  expect(after).toContain('hidden · 36 chars')
  expect(after).not.toContain('492b')
  await ui.unmount()
})

test('keys the code reads but .env does not set are named', () => {
  const js = "const a = process.env.MUX_TOKEN_ID; const b = process.env['STRIPE_KEY']; if (process.env.NODE_ENV) {}"
  const py = "import os\nkey = os.environ.get('OPENAI_API_KEY')\nurl = os.getenv(\"DB_URL\")"
  expect(readsIn(js).sort()).toEqual(['MUX_TOKEN_ID', 'STRIPE_KEY'])
  expect(readsIn(py).sort()).toEqual(['DB_URL', 'OPENAI_API_KEY'])
  expect(missingKeys([...readsIn(js), ...readsIn(py)], ['OPENAI_API_KEY', 'UNUSED'])).toEqual(['DB_URL', 'MUX_TOKEN_ID', 'STRIPE_KEY'])
})

test('env_list tells Claude which keys the code needs and the pane marks them', async ($, on) => {
  const disk: Record<string, string> = { '/p/.env': 'OPENAI_API_KEY=sk-test-000000000000000000001234\n', '/p/src/upload.ts': 'mux(process.env.MUX_TOKEN_ID, process.env.MUX_TOKEN_SECRET)', '/p/node_modules/x.js': 'process.env.IGNORED_KEY' }
  on('fs.read', async (_$: any, e: any) => { if (!(e.path in disk)) throw new Error('missing'); return { value: disk[e.path] } as any })
  on('fs.list', async (_$: any, e: any) => {
    const kids = new Map<string, 'file' | 'dir'>()
    for (const k of Object.keys(disk)) if (k.startsWith(e.path + '/')) { const rest = k.slice(e.path.length + 1); const [h, ...t] = rest.split('/'); kids.set(h, t.length ? 'dir' : 'file') }
    return { value: [...kids].map(([name, kind]) => ({ name, kind })) } as any
  })
  on('ui.render', async () => null as any)
  const r: any = await $.tool.call({ tool: 'mcp__secrets-guard__env_list', file: '/p/.env' } as any)
  expect(String(r.result)).toContain('does not set: MUX_TOKEN_ID, MUX_TOKEN_SECRET')
  expect(String(r.result)).not.toContain('IGNORED_KEY')
  const ui = await $.ui.mount({ plugin: 'secrets-guard', surface: 'terminal', component: 'Pane', requestId: 'env', props: {}, viewport: { columns: 72, rows: 30 } } as any)
  const drawn = JSON.stringify(await ui.drawn())
  expect(drawn).toContain('2 missing')
  expect(drawn).toContain('your code reads it, not set')
  await ui.unmount()
})

test('two requests queue up: the second waits until the first is stored', async ($, on) => {
  const disk: Record<string, string> = {}
  const said: string[] = []
  on('fs.read', async (_$: any, e: any) => { if (!(e.path in disk)) throw new Error('missing'); return { value: disk[e.path] } as any })
  on('fs.write', async (_$: any, e: any) => { disk[e.path] = String(e.text); return { value: undefined } as any })
  on('fs.list', async () => ({ value: [] }) as any)
  on('ui.render', async () => null as any)
  on('ui.open', async () => ({ value: { opened: true } }) as any)
  on('ui.toast', async () => ({ value: undefined }) as any)
  on('prompt.submit', async (_$: any, e: any) => { said.push(e.text); return { text: e.text } as any })
  await $.tool.call({ tool: 'mcp__secrets-guard__env_request', key: 'MUX_TOKEN_ID', why: 'id', file: '/q/.env' } as any)
  await $.tool.call({ tool: 'mcp__secrets-guard__env_request', key: 'MUX_TOKEN_SECRET', why: 'secret', file: '/q/.env' } as any)
  const ui = await $.ui.mount({ plugin: 'secrets-guard', surface: 'terminal', component: 'Pane', requestId: 'env', props: {}, viewport: { columns: 72, rows: 30 } } as any)
  expect(JSON.stringify(await ui.drawn())).toContain('1 of 2, then MUX_TOKEN_SECRET')
  await ui.input({ key: 'paste', text: 'first-value-12345' })
  const next = JSON.stringify(await ui.drawn())
  expect(next).toContain('MUX_TOKEN_SECRET')
  expect(next).not.toContain('1 of 2')
  await ui.input({ key: 'paste', text: 'second-value-67890' })
  expect(disk['/q/.env']).toBe('MUX_TOKEN_ID=first-value-12345\nMUX_TOKEN_SECRET=second-value-67890\n')
  expect(said.length).toBe(2)
  await ui.unmount()
})

{
  "extends": "./.claude-plugin/types/tsconfig.json"
}

export type EnvRequest = {
  key: string
  why: string
  where: string[]
  link?: string
  format?: string
  minLength: number
  file: string
}

export type EnvKeyRow = { name: string; masked: string }

declare module 'claude-code' {
  interface PluginState {
    'secrets-guard': { requests: EnvRequest[]; keys: EnvKeyRow[]; file: string; error: string; missing: string[] }
  }
}

// Pure helpers for the .env pane: read key names, mask values, check a pasted value, write it back.

export type EnvKey = { name: string; masked: string }

const LINE = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/

const unquote = (v: string) => v.trim().replace(/^(['"])(.*)\1$/, '$2')

// Shows that a value is there and how long it is. No character of the value is ever shown.
export function maskValue(v: string): string {
  if (!v) return 'empty'
  return `hidden · ${v.length} chars`
}

export function listKeys(text: string): EnvKey[] {
  const out: EnvKey[] = []
  for (const line of text.split('\n')) {
    const m = line.match(LINE)
    if (m) out.push({ name: m[1], masked: maskValue(unquote(m[2])) })
  }
  return out
}

// Sets one key, replacing its line if it is there, adding it at the end if not.
export function setKey(text: string, name: string, value: string): string {
  const v = /[\s#"'$]/.test(value) ? `"${value.replace(/(["\\$])/g, '\\$1')}"` : value
  const lines = text.split('\n')
  const i = lines.findIndex(l => l.match(LINE)?.[1] === name)
  if (i >= 0) lines[i] = `${name}=${v}`
  else {
    if (lines.length && lines[lines.length - 1] === '') lines.pop()
    lines.push(`${name}=${v}`, '')
  }
  return lines.join('\n')
}

export const KEY_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/

// Returns why a pasted value is wrong, or null when it looks right.
export function checkValue(value: string, minLength = 8): string | null {
  if (!value.trim()) return 'Nothing was pasted.'
  if (/\n/.test(value)) return 'The value has a line break in it. Paste one line.'
  if (value.trim().length < minLength) return `That is ${value.trim().length} characters. This key is at least ${minLength}.`
  return null
}

// The variable names code reads, from the usual ways JavaScript, TypeScript, Python, Deno and
// shell scripts ask for them.
const READS: RegExp[] = [
  /process\.env\.([A-Z_][A-Z0-9_]*)/g,
  /process\.env\[\s*['"]([A-Z_][A-Z0-9_]*)['"]\s*\]/g,
  /import\.meta\.env\.([A-Z_][A-Z0-9_]*)/g,
  /os\.environ\[\s*['"]([A-Z_][A-Z0-9_]*)['"]\s*\]/g,
  /os\.(?:environ\.get|getenv)\(\s*['"]([A-Z_][A-Z0-9_]*)['"]/g,
  /Deno\.env\.get\(\s*['"]([A-Z_][A-Z0-9_]*)['"]/g,
]
const BUILT_IN = new Set(['NODE_ENV', 'HOME', 'PATH', 'PWD', 'USER', 'SHELL', 'TERM', 'CI', 'PORT', 'TZ', 'LANG'])

export function readsIn(code: string): string[] {
  const out = new Set<string>()
  for (const re of READS) for (const m of code.matchAll(re)) if (!BUILT_IN.has(m[1])) out.add(m[1])
  return [...out]
}

// Names the code reads that the .env file does not set: the ones that break at run time.
export function missingKeys(read: string[], set: string[]): string[] {
  const have = new Set(set)
  return [...new Set(read)].filter(n => !have.has(n)).sort()
}

export const CODE_FILE = /\.(m?[jt]sx?|cjs|py|sh)$/

import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { EnvRequest } from '../types'
import { checkValue, CODE_FILE, KEY_NAME, listKeys, missingKeys, readsIn, setKey } from './envfile'
import { isSecretFile, maskKeys, secretCommand } from './secrets'

// Keeps keys out of the chat. Claude cannot open .env, SSH keys, .pem files or credential
// files, cannot run commands that print them, and any key that still shows up in a
// command's output is masked before Claude reads it.
// It also gives Claude a safe way to USE a key: env_list shows key names with masked values,
// and env_request opens a pane where you paste the value. The value goes straight into .env.
// Claude only ever hears "KEY is now set".
// LIMIT: it masks command output, not the text of ordinary files Claude reads.

const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'NotebookEdit'])
const PANE = 'env'
const ENV_HINT = 'To see which keys exist, call env_list. To get a missing key, call env_request: the user pastes it into a pane and it goes straight into .env.'

const requests = atom({ plugin: 'secrets-guard', key: 'requests' } as const, []) // first one shows, the rest wait their turn
const keys = atom({ plugin: 'secrets-guard', key: 'keys' } as const, [])
const fileAtom = atom({ plugin: 'secrets-guard', key: 'file' } as const, '.env')
const error = atom({ plugin: 'secrets-guard', key: 'error' } as const, '')
const missing = atom({ plugin: 'secrets-guard', key: 'missing' } as const, [])

const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build', '.next', 'venv', '.venv', '__pycache__'])

// Reads the project's code (3 folders deep, 400 files at most) for the variable names it asks for.
async function codeReads($: any, root: string): Promise<string[]> {
  const names = new Set<string>()
  let seen = 0
  const walk = async (dir: string, depth: number) => {
    const entries = await $.fs.list(dir).catch(() => [])
    for (const e of entries) {
      if (seen >= 400) return
      const path = `${dir}/${e.name}`
      if (e.kind === 'dir' && depth < 3 && !SKIP_DIRS.has(e.name)) await walk(path, depth + 1)
      else if (e.kind === 'file' && CODE_FILE.test(e.name)) {
        seen++
        for (const n of readsIn(await $.fs.read(path).catch(() => ''))) names.add(n)
      }
    }
  }
  await walk(root, 0)
  return [...names]
}

const TOOLS = [
  {
    name: 'env_list',
    description: 'List the key names in the project .env file, with each value masked (for example ●●●●492b). Never shows a value.',
    inputSchema: { type: 'object', properties: { file: { type: 'string', description: 'Defaults to .env in the working folder' } } },
  },
  {
    name: 'env_request',
    description:
      'Ask the user for one secret value, such as an API key. A pane opens with a card that says what the key is for and where to find it. The user pastes it there and it is written to .env. You never see the value: you get "[env] KEY is now set in .env" as the next message. Never ask for a key in the chat.',
    inputSchema: {
      type: 'object',
      properties: {
        key: { type: 'string', description: 'The variable name, for example MUX_TOKEN_ID' },
        why: { type: 'string', description: 'One line: what the key is for' },
        where: { type: 'array', items: { type: 'string' }, description: 'Short numbered steps to find the key' },
        link: { type: 'string', description: 'The dashboard page where the key lives' },
        format: { type: 'string', description: 'What the value looks like, for example "UUID, 36 characters"' },
        minLength: { type: 'number', description: 'Shortest valid length. Defaults to 8' },
        file: { type: 'string', description: 'Defaults to .env in the working folder' },
      },
      required: ['key', 'why'],
    },
  },
]

let ready: Promise<void> | undefined
function setup($: any): Promise<void> {
  ready ??= doSetup($).catch(() => undefined) // a missing engine call must not stop the hooks
  return ready
}
async function doSetup($: any) {
  for (const t of TOOLS) await $.tool.register(t)
  await $.command.register({ name: 'env', description: 'Open the .env pane: key names with masked values' })
}

async function loadKeys($: any, file: string) {
  const text = await $.fs.read(file).catch(() => '')
  const list = listKeys(text)
  await update($, keys, () => list)
  await update($, fileAtom, () => file)
  const root = file.includes('/') ? file.slice(0, file.lastIndexOf('/')) || '/' : await $.session.cwd().catch(() => '.')
  const reads = await codeReads($, root).catch(() => [] as string[])
  await update($, missing, () => missingKeys(reads, list.map(k => k.name)))
  return text as string
}

async function save($: any, req: EnvRequest, value: string) {
  const bad = checkValue(value, req.minLength)
  if (bad) {
    await update($, error, () => bad)
    return
  }
  const text = await $.fs.read(req.file).catch(() => '')
  await $.fs.write(req.file, setKey(text, req.key, value.trim()))
  await update($, error, () => '')
  await update($, requests, list => list.filter(r => r.key !== req.key))
  await loadKeys($, req.file)
  $.ui.toast(`${req.key} saved to ${req.file.split('/').pop()}`)
  void $.prompt.submit({ text: `[env] ${req.key} is now set in ${req.file.split('/').pop()}. Continue.` })
}

async function skip($: any, req: EnvRequest) {
  await update($, requests, list => list.filter(r => r.key !== req.key))
  await update($, error, () => '')
  void $.prompt.submit({ text: `[env] The user skipped ${req.key} for now. Carry on without it.` })
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await setup($)
    return next(e)
  })

  on('command.run', { command: 'env' }, async $ => {
    await setup($)
    await loadKeys($, await read($, fileAtom))
    const list = await read($, keys)
    await $.ui.open({ id: PANE, title: '.env' })
    return { text: `${list.length} key(s) in .env. Values stay masked.` }
  })

  on('tool.call', { tool: 'mcp__secrets-guard__env_list' }, async ($, e: any) => {
    await setup($)
    const file = String(e.file || '.env')
    await loadKeys($, file)
    const list = await read($, keys)
    const gone = await read($, missing)
    const lines = [list.length ? `${list.length} key(s) in ${file} (values hidden):\n${list.map(k => `${k.name}  ${k.masked}`).join('\n')}` : `${file} has no keys yet.`]
    if (gone.length) lines.push(`The code reads ${gone.length} key(s) that ${file} does not set: ${gone.join(', ')}. Call env_request for each.`)
    else if (!list.length) lines.push('Call env_request to ask the user for one.')
    return { result: lines.join('\n') }
  })

  on('tool.call', { tool: 'mcp__secrets-guard__env_request' }, async ($, e: any) => {
    await setup($)
    const key = String(e.key ?? '').trim()
    if (!KEY_NAME.test(key)) return { result: `"${key}" is not a valid variable name. Use letters, digits and _ only.` }
    const file = String(e.file || '.env')
    const req: EnvRequest = {
      key,
      why: String(e.why ?? ''),
      where: Array.isArray(e.where) ? e.where.map(String).slice(0, 6) : [],
      link: e.link ? String(e.link) : undefined,
      format: e.format ? String(e.format) : undefined,
      minLength: Number(e.minLength) > 0 ? Number(e.minLength) : 8,
      file,
    }
    await loadKeys($, file)
    await update($, error, () => '')
    await update($, requests, list => [...list.filter(r => r.key !== key), req])
    await $.ui.open({ id: PANE, title: '.env', focus: true } as any)
    return { result: `Asked the user to paste ${key} into the .env pane. Stop here and wait: the next message will say "[env] ${key} is now set". Do not ask for the value in the chat.` }
  })

  on('tool.call', async ($, e: any, next) => {
    if (FILE_TOOLS.has(e.tool)) {
      const p = String(e.file_path ?? e.notebook_path ?? '')
      if (isSecretFile(p)) {
        $.ui.toast(`Stopped Claude opening ${p.split('/').pop()}`)
        return { deny: `secrets-guard: ${p} holds secrets, so Claude may not open it. ${ENV_HINT}` }
      }
      return next(e)
    }
    if (e.tool === 'Grep' && isSecretFile(String(e.path ?? ''))) {
      return { deny: `secrets-guard: ${e.path} holds secrets, so Claude may not search inside it. ${ENV_HINT}` }
    }
    if (e.tool !== 'Bash') return next(e)

    const why = secretCommand(String(e.command ?? ''))
    if (why) {
      $.ui.toast('Stopped a command that would print a secret')
      return { deny: `secrets-guard: ${why}. Use the variable by name instead (for example "$API_KEY" inside the command) so its value never reaches the chat. ${ENV_HINT}` }
    }
    const ran: any = await next(e)
    if (!ran?.result || typeof ran.result !== 'object') return ran
    const out = maskKeys(String(ran.result.stdout ?? ''))
    const err = maskKeys(String(ran.result.stderr ?? ''))
    if (out.count + err.count === 0) return ran
    $.ui.toast(`Masked ${out.count + err.count} key(s) in command output`)
    return { result: { ...ran.result, stdout: out.text, stderr: err.text } }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Input } = $.ui.resolve(e) as any
    const queue = await read($, requests)
    const req = queue[0]
    const list = await read($, keys)
    const gone = await read($, missing)
    const file = (await read($, fileAtom)).split('/').pop()
    const bad = await read($, error)
    const accent = '#D97557'
    return (
      <Box flexDirection="column">
        {req && (
          <Box flexDirection="column" borderStyle="single" borderColor={accent} paddingX={1}>
            <Text>
              <Text bold color="black" backgroundColor={accent}>{' KEY REQUEST '}</Text>
              <Text bold>{`  ${req.key}`}</Text>
              {queue.length > 1 && <Text dimColor>{`  1 of ${queue.length}, then ${queue.slice(1).map(r => r.key).join(', ')}`}</Text>}
            </Text>
            {req.why && <Text>{`For    ${req.why}`}</Text>}
            {req.where.map((s, i) => (
              <Text key={`w${i}`}>{`${i === 0 ? 'Find   ' : '       '}${s}`}</Text>
            ))}
            {req.link && <Text color={accent}>{`Open   ${req.link}`}</Text>}
            {req.format && <Text dimColor>{`Shape  ${req.format}`}</Text>}
            <Input
              key="paste"
              label="Value  "
              placeholder={`goes into ${file} only. Claude never reads it`}
              value=""
              submitLabel="store it"
              autoFocus
              onSubmit={(v: string) => void save($, req, v)}
            />
            {bad && <Text color="red">{`Not stored: ${bad}`}</Text>}
            <Box flexDirection="row">
              <Button key="skip" label="Not now" onPress={() => void skip($, req)} />
            </Box>
          </Box>
        )}
        <Box flexDirection="column" marginTop={req ? 1 : 0}>
          <Text bold color={accent}>{`${file} · ${list.length} set${gone.length ? ` · ${gone.length} missing` : ''}`}</Text>
          {list.length === 0 && gone.length === 0 && <Text dimColor>Nothing set yet.</Text>}
          {list.map(k => (
            <Text key={`k-${k.name}`}>
              <Text color="green">{'✓ '}</Text>
              <Text>{k.name.padEnd(22)}</Text>
              <Text dimColor>{k.masked}</Text>
            </Text>
          ))}
          {gone.map(n => (
            <Text key={`m-${n}`}>
              <Text color="red">{'✕ '}</Text>
              <Text>{n.padEnd(22)}</Text>
              <Text color="red">your code reads it, not set</Text>
            </Text>
          ))}
          <Text dimColor>Claude sees key names and lengths. Never a character of a value.</Text>
        </Box>
      </Box>
    )
  })
}

// What counts as a secret file, which commands would print one, and how keys are masked.

const SAFE_ENV = /\.env\.(example|sample|template|dist)$/i
const SECRET_FILE =
  /(^|\/)(\.env(\.[\w.-]+)?|id_(rsa|dsa|ecdsa|ed25519)|[^/]+\.(pem|key|p12|pfx|keystore|jks)|\.netrc|\.npmrc|\.pypirc|credentials(\.json)?|secrets?\.(json|ya?ml|toml)|service[-_]account[^/]*\.json)$/i

export function isSecretFile(path: string): boolean {
  const p = path.replace(/\/+$/, '')
  return SECRET_FILE.test(p) && !SAFE_ENV.test(p)
}

const READERS = new Set(['cat', 'less', 'more', 'head', 'tail', 'bat', 'grep', 'rg', 'awk', 'sed', 'strings', 'xxd', 'od', 'hexdump', 'base64', 'source', '.', 'nl', 'cut', 'sort', 'jq', 'yq', 'diff', 'type'])

// Returns why a shell command would print a secret, or null when it would not.
export function secretCommand(cmd: string): string | null {
  const parts = cmd.split(/&&|\|\||[;|\n]/).map(s => s.trim()).filter(Boolean)
  for (const part of parts) {
    const w = part.split(/\s+/).map(x => x.replace(/^['"]|['"]$/g, ''))
    const head = (w[0] ?? '').split('/').pop() ?? ''
    if ((head === 'env' || head === 'printenv' || head === 'export' || head === 'set') && w.length === 1) {
      return `\`${head}\` prints every environment variable, keys included`
    }
    const file = w.slice(1).find(a => isSecretFile(a.replace(/^[<>]+/, '')))
    if (READERS.has(head) && file) return `\`${head}\` would print ${file}`
    const redirected = part.match(/<\s*(\S+)/)?.[1]
    if (redirected && isSecretFile(redirected)) return `the command reads ${redirected}`
  }
  return null
}

const KEY_PATTERNS: RegExp[] = [
  /\bsk-(?:ant-|proj-)?[A-Za-z0-9_-]{20,}/g, // Anthropic, OpenAI
  /\bAKIA[0-9A-Z]{16}\b/g, // AWS access key id
  /\bgh[pousr]_[A-Za-z0-9]{30,}/g, // GitHub
  /\bgithub_pat_[A-Za-z0-9_]{30,}/g,
  /\bxox[abprs]-[A-Za-z0-9-]{10,}/g, // Slack
  /\bAIza[0-9A-Za-z_-]{35}\b/g, // Google
  /\b(?:sk|rk|pk)_live_[A-Za-z0-9]{16,}/g, // Stripe
  /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g,
]
const ASSIGNED = /\b([A-Z0-9_]*(?:API_KEY|SECRET|TOKEN|PASSWORD|PASSWD)[A-Z0-9_]*)(\s*[=:]\s*)(["']?)([^\s"']{8,})\3/gi

export function maskKeys(text: string): { text: string; count: number } {
  let count = 0
  let out = text
  for (const re of KEY_PATTERNS) {
    out = out.replace(re, m => {
      count++
      return m.startsWith('-----') ? '[private key masked by secrets-guard]' : `${m.slice(0, 4)}…[masked]`
    })
  }
  out = out.replace(ASSIGNED, (m, name, sep, q, value) => {
    if (value.includes('[masked]')) return m
    count++
    return `${name}${sep}${q}[masked]${q}`
  })
  return { text: out, count }
}

